/* Callout properties - applied after others */
body .callout[data-callout*="text-glow"] {
    text-shadow: 0 0 9px var(--glow-color1);
}
body .callout[data-callout*="text-light-glow"] {
    text-shadow: 0 0 4px var(--glow-color2);
}
body .callout[data-callout*="callout-glow"]  {
    box-shadow: inset 0 0 15px color-mix(in srgb, var(--glow-color2), transparent 20%);
    text-shadow: 0 0 3px var(--glow-color2);
}
body .callout[data-callout*="cutout"] {
    box-shadow: inset 5px 5px 15px color-mix(in srgb, var(--shadow-color), transparent 50%);
	border: none;
}
body .callout[data-callout*="no-icon"]  {
    --callout-icon: none;
}
body .callout[data-callout*="no-title"] {
	--callout-title-size: 0px;
	padding-top: 2px;
}
body .callout[data-callout*="no-title"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="no-border"] {
	border: none;
}
body .callout[data-callout*="solid-border"] {
	border-style: solid;
}
body .callout[data-callout*="no-bg"] {
	background: none;
}
body .callout[data-callout*="no-callout-color"] {
	background-color: transparent;
}
body .callout[data-callout*="no-stamp"] {
	background-image: none;
}
body .callout[data-callout*="no-glow"] {
	box-shadow: none;
}
body .callout[data-callout*="white-text"] {
	color: white;
}
body .callout[data-callout*="black-text"] {
	color: black;
}
body .callout[data-callout*="nothing"] {
    --callout-icon: none;
	background: none;
}
body .callout[data-callout*="only-bg"],
body .callout[data-callout*="nothing"] {
	--callout-title-size: 0px;
	padding-top: 2px;
	box-shadow: none;
	border: none;
}
body .callout[data-callout*="only-bg"] .callout-title,
body .callout[data-callout*="nothing"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="callout-minheight-100"] {
	min-height: 100px;
}
body .callout[data-callout*="callout-minheight-300"] {
	min-height: 300px;
}
body .callout[data-callout*="callout-minheight-500"] {
	min-height: 500px;
}
body .callout[data-callout*="callout-minheight-700"] {
	min-height: 700px;
}
body .callout[data-callout*="fixed-bg"] {
	background-attachment: fixed;
	background-size: 100% auto;
	background-position-x: 0px;
	background-position-y: 10%;
}
body .callout[data-callout*="mask-no-repeat"] {
	-webkit-mask-repeat: no-repeat;
}
body .callout[data-callout*="bg-no-repeat"] {
	background-repeat: no-repeat;
}
body .callout[data-callout*="small-bg"] {
	background-size: 50% auto;
}
body .callout[data-callout*="big-bg"] {
