/* "Blends" - either mix-blend-mode or backdrop-filter */

.whim-blend-weakblur {
    backdrop-filter: brightness(0.95) blur(1px);
}
.whim-blend-blur {
    backdrop-filter: brightness(0.95) blur(3.5px);
}
.whim-blend-strongblur {
    backdrop-filter: brightness(0.95) blur(10px);
}

.whim-blend-multiply {
	mix-blend-mode: multiply;
}
.whim-blend-overlay {
	mix-blend-mode: overlay;
}
.whim-blend-soft {
	mix-blend-mode: soft-light;
}
.whim-blend-hard {
	mix-blend-mode: hard-light;
}
.whim-blend-dodge {
	mix-blend-mode: color-dodge;
}
.whim-blend-burn {
	mix-blend-mode: color-burn;
}
.whim-blend-difference {
	mix-blend-mode: difference;
}
.whim-blend-exclusion {
	mix-blend-mode: exclusion;
}
.whim-blend-hue {
	mix-blend-mode: hue;
}
.whim-blend-color {
	mix-blend-mode: color;
}


/* Filters */

.whim-filter-pink {
	filter: invert(10%) sepia(75%) saturate(120%) hue-rotate(-100deg) brightness(100%) contrast(125%);
}
.whim-filter-red {
	filter: invert(10%) sepia(75%) saturate(160%) hue-rotate(-80deg) brightness(100%) contrast(125%);
}
.whim-filter-brown {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(-30deg) brightness(110%) contrast(125%);
}
.whim-filter-yellow {
	filter: invert(10%) sepia(75%) saturate(150%) hue-rotate(0deg) brightness(125%) contrast(125%);
}
.whim-filter-green {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(80deg) brightness(115%) contrast(125%);
}
.whim-filter-blue {
	filter: invert(10%) sepia(75%) saturate(160%) hue-rotate(200deg) brightness(100%) contrast(125%);
}
.whim-filter-purple {
	filter: invert(10%) sepia(75%) saturate(120%) hue-rotate(225deg) brightness(100%) contrast(125%);
}
.whim-filter-mist {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(225deg) brightness(110%) contrast(125%);
}
.whim-filter-darker {
    filter: brightness(0.8) contrast(1.1);
}
.whim-bg-filter-miximagestamp, 
.whim-filter-lighter {
    filter: brightness(1.25) contrast(1.1);
}
.whim-filter-grayscale {
	filter: grayscale(100%);
}
.whim-filter-sepia {
	filter: sepia(100%);
}
.whim-filter-invert {
    filter: invert(100%);
}
.whim-filter-invert img {
    filter: invert(100%);
}
.whim-filter-invert-darker {
    filter: invert(100%) brightness(60%) contrast(200%);
}
.whim-filter-invert-darker img {
    filter: invert(100%);
}
.whim-filter-terminal {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(80deg) brightness(1.15) contrast(2);
}
.whim-filter-pseudo-light-mode-higher-contrast {
    filter: invert(100%) hue-rotate(180deg) brightness(1.05) contrast(1.2);
}
.whim-filter-pseudo-light-mode-higher-contrast img {
    filter: invert(100%) hue-rotate(180deg) brightness(0.95) contrast(0.8);
}
.whim-filter-pseudo-light-mode {
    filter: invert(100%) hue-rotate(180deg);
}
.whim-filter-pseudo-light-mode img {
    filter: invert(100%) hue-rotate(180deg);
}
.whim-filter-rotatehue {
	filter: saturate(60%) hue-rotate(var(--strongest-shift-hue-deg)) brightness(120%);
}
.whim-filter-shift {
	filter: hue-rotate(var(--shift-hue-deg));
}
.whim-filter-shift2 {
	--shift-hue-deg: 100deg;
	filter: hue-rotate(var(--shift-hue-deg));
}
.whim-filter-shift3 {
	--shift-hue-deg: 200deg;
	filter: hue-rotate(var(--shift-hue-deg));
}
.whim-filter-shift4 {
	--shift-hue-deg: -200deg;
	filter: hue-rotate(var(--shift-hue-deg));
}

.whim-filter-highcontrast {
	filter: brightness(120%) contrast(170%);
}
.whim-filter-lowcontrast {
	filter: brightness(65%) contrast(50%);
}
.whim-filter-highersat {
	filter: saturate(190%);
}
.whim-filter-lowersat {
	filter: saturate(70%);
}


/* filter mixes */

.whim-filter-highersat-rotatehue {
	filter: saturate(120%) hue-rotate(var(--strongest-shift-hue-deg)) brightness(120%);
}

.whim-filter-lowersat-rotatehue {
	filter: saturate(30%) hue-rotate(var(--strongest-shift-hue-deg)) brightness(120%);
}

.whim-filter-highersat-shift {
	filter: hue-rotate(var(--shift-hue-deg)) saturate(190%);
}

.whim-filter-lowersat-shift {
	filter: hue-rotate(var(--shift-hue-deg)) saturate(70%);
}

.whim-filter-highersat-shift2 {
	--shift-hue-deg: 100deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(190%);
}

.whim-filter-lowersat-shift2 {
	--shift-hue-deg: 100deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(70%);
}

.whim-filter-highersat-shift3 {
	--shift-hue-deg: 200deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(190%);
}

.whim-filter-lowersat-shift3 {
	--shift-hue-deg: 200deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(70%);
}

.whim-filter-highersat-shift4 {
	--shift-hue-deg: -200deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(190%);
}

.whim-filter-lowersat-shift4 {
	--shift-hue-deg: -200deg;
	filter: hue-rotate(var(--shift-hue-deg)) saturate(70%);
}



/* Box-shadows */

.whim-shadow {
	box-shadow: 0px 3px 8px 3px rgba(0, 0, 0, 0.3);
	margin: 10px;
}
.whim-shadowmore {
	box-shadow: 0px 3px 8px 3px rgba(0, 0, 0, 0.6);
	margin: 10px;
}
.whim-shadowinset {
	box-shadow: inset 2px 2px 10px 10px rgba(0, 0, 0, 0.2);
}
.whim-glow {
	box-shadow: inset 0px 0px 4px 4px color-mix(in srgb, var(--whim-color), transparent 85%);
    text-shadow: 0 0 3px var(--light-whim);
}
.whim-glowmore {
	box-shadow: inset 0px 0px 10px 10px color-mix(in srgb, var(--whim-color), transparent 85%);
    text-shadow: 0 0 9px var(--lw);
}
.whim-cutout {
	box-shadow: inset 20px 20px 20px 20px rgba(0, 0, 0, 0.2);
}

/* BG colors, patterns, and images */

.whim-draw-faint {
	--nbg-draw-transparency: 95%;
}
.whim-draw-more {
	--nbg-draw-transparency: 75%;
}
.whim-draw-evenmore {
	--nbg-draw-transparency: 35%;
}
.whim-draw-opaque {
	--nbg-draw-transparency: 1%;
}
.whim-color-faint {
	--nbg-solid-transparency: 95%;
}
.whim-color-more {
	--nbg-solid-transparency: 75%;
}
.whim-color-evenmore {
	--nbg-solid-transparency: 35%;
}
.whim-color-opaque {
	--nbg-solid-transparency: 5%;
}
  
.whim-emboss-abstract,
