body.whim-bg-diamonds .workspace, .whim-bg-diamonds {
	background: repeating-radial-gradient(
		circle,
		color-mix(in srgb, var(--nbg-draw-color), transparent 80%) 0 3px,
		var(--nbg-solid-color) 3px 110px
		)
		content-box border-box 0% 0% / 200px 200px repeat;
	background-position: 50% 30%;
}

body.whim-bg-grid .workspace, .whim-bg-grid {
	--grid-line-color: color-mix(in srgb, var(--nbg-draw-color), transparent 85%);
	background: 
		repeating-linear-gradient(90deg, var(--nbg-solid-color), var(--nbg-solid-color) 30px, var(--grid-line-color) 30px, var(--grid-line-color) 32px),
		repeating-linear-gradient(0deg, var(--nbg-solid-color), var(--nbg-solid-color) 30px, var(--grid-line-color) 30px, var(--grid-line-color) 32px);
	background-position: 50% 50%;
}

body.whim-bg-gems .workspace, .whim-bg-gems {
	--gemt: 90%;
	--gemw: 200px;
	--gemh: 200px;
	background: 
		linear-gradient(
			135deg,
			var(--nbg-solid-color),
			color-mix(in srgb, var(--dw), transparent 20%)
		),
		repeating-conic-gradient(
			from 98deg,
			color-mix(in srgb, var(--nbg-draw-color), transparent var(--gemt)) 0%, 
			var(--nbg-solid-color) 85%
		)
		content-box border-box 0% 0% / var(--gemw) var(--gemh) repeat, 
		repeating-conic-gradient(
			from 188deg,
			color-mix(in srgb, var(--nbg-draw-color), transparent var(--gemt)) 0%, 
			var(--nbg-solid-color) 85%
		)
		content-box border-box 0% 0% / var(--gemw) var(--gemh) repeat, 
		repeating-conic-gradient(
			from -80deg,
			color-mix(in srgb, var(--nbg-draw-color), transparent var(--gemt)) 0%, 
			color-mix(in srgb, var(--dcon), transparent var(--gemt)) 85%
		)
		content-box border-box 0% 0% / var(--gemw) var(--gemh) repeat, 
		repeating-conic-gradient(
			from 9deg,
			color-mix(in srgb, var(--nbg-draw-color), transparent var(--gemt)) 0%,
			color-mix(in srgb, var(--con), transparent var(--gemt)) 85%
		)
		content-box border-box 0% 0% / var(--gemw) var(--gemh) repeat
		;
}

